      // each functional method's declaring trait or object, and the traits that it extends
      // at any depth, read on the declarations themselves, with no instance of their
      // static parameters
      def declarer(f: JavaFunctional): Option[TypeConsIndex] =
        toOption(typeAnalyzer.traits.typeCons(f.asInstanceOf[JavaFunctionalMethod].declaringTrait))
      def above(d: TypeConsIndex): List[TypeConsIndex] = d match {
        case di: TraitIndex =>
          typeAnalyzer.extend(toListFromImmutable(di.staticParameters), None)
                      .ancestors(STypesUtil.declToTraitType(di.ast)).toList.flatMap {
            case at: TraitType => toOption(typeAnalyzer.traits.typeCons(at.getName)).toList
            case _ => Nil }
        case _ => Nil }
      val declared = arrows.map(a => {
        val d = a._3.filter(isFunctionalMethod).flatMap(declarer)
        (a, d, d.map(above).getOrElse(Nil)) })
      // an abstract one that a functional method of a trait or object extending its
      // declarer implements with the same parameter types
      def implemented(a: (ArrowType,Option[Int],Option[JavaFunctional]), ad: Option[TypeConsIndex]) =
        isAbstract(a) && ad.isDefined &&
        declared.exists { case (c, cd, cabove) =>
          !(c._1 eq a._1) && c._2 == a._2 && cd.isDefined && !(cd.get eq ad.get) &&
          cabove.exists(_ eq ad.get) && globalOracle.equiv(a._1, c._1) }
      declared.filter { case (a, ad, _) => !implemented(a, ad) }.map(_._1)
    }

    // for functional methods: every one the type provides, abstract ones included, as
    // toMethodArrows reads dotted ones; but an abstract one implemented by a declaration
    // of a subtype with the same parameter types
    private def toFunctionalMethodArrows(set: Set[(JavaFunctional, StaticTypeReplacer, TraitType)],
                                         oracle: OverloadingOracle):
        List[(ArrowType,Option[Int],Option[JavaFunctional])] = {
      val arrows = set.filter(p => p match { case (f, _, _) => isFunctionalMethod(f)})
         .toList.map(p => p match { case (f, replacer, tt) =>
              //TODO: Figure out whether I should get the lifted parameters or not. The original code DID.  I think the answer is NO. 2/21/2012
              val (sparams, apart) = ownStaticParamsApart(f)
              ((selfTyped(NF.makeArrowType(f.getSpan,
                                replacer.replaceIn(apart(paramsToType(f.parameters, f.getSpan))),
                                replacer.replaceIn(apart(f.getReturnType.unwrap)),
				sparams), f,
                  (ps: JavaList[Param]) => NF.makeArrowType(f.getSpan,
                                replacer.replaceIn(apart(paramsToType(ps, f.getSpan))),
                                replacer.replaceIn(apart(f.getReturnType.unwrap)),
                                sparams)),
               Some(f.asInstanceOf[JavaFunctionalMethod].selfPosition),
	       Some(f)), tt)})
      def implemented(a: (ArrowType,Option[Int],Option[JavaFunctional]), tt: TraitType) =
        a._3.get.asInstanceOf[JavaFunction].body.isNone &&
        arrows.exists(p => p match { case (c, ctt) =>
          !(c._1 eq a._1) && c._2 == a._2 && typeAnalyzer.lteq(ctt, tt) && !typeAnalyzer.lteq(tt, ctt) &&
          oracle.equiv(a._1, c._1) })
      arrows.filter(p => !implemented(p._1, p._2)).map(_._1)
    }

    /* A declaration's parameter types without self, as the trait or object being checked
     * has them, over the method's own static parameters renamed apart (ownStaticParamsApart):
     * what STypesUtil.providedMethods compares. */
    private def paramsWithoutSelf(d: (JavaFunctional, StaticTypeReplacer, TraitType)): Option[Type] = d match {
      case (f, replacer, _) =>
        val ps = toListFromImmutable(f.parameters)
        val kept = f match {
          case m: JavaFunctionalMethod => ps.zipWithIndex.filter(_._2 != m.selfPosition).map(_._1)
          case _ => ps }
        STypesUtil.paramsToType(kept, f.getSpan).map { t =>
          val (sparams, apart) = ownStaticParamsApart(f)
          replacer.replaceIn(insertStaticParams(apart(t), sparams)) }
    }

    // for dotted methods
    private def toMethodArrows(set: Set[(JavaFunctional, StaticTypeReplacer, TraitType)])
                           : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      set.filter(p => p match { case (f, _, _) => isDeclaredMethod(f)})
         .toList.map(p => p match { case (f, replacer, _) =>
              val (sparams, apart) = ownStaticParamsApart(f)
              (NF.makeArrowType(f.getSpan,
	                        replacer.replaceIn(apart(paramsToType(f.asInstanceOf[JavaMethod].selfType.unwrap, f.parameters, f.getSpan))),
                		replacer.replaceIn(apart(f.getReturnType.unwrap)),
				sparams),
               None,
	       Some(f))})

    /* An inherited method's own static parameters, each whose name is a static parameter
     * of the trait or object being checked renamed apart, so that the arguments the
     * replacer puts in place of the declaring trait's parameters are not captured. */
    private def ownStaticParamsApart(f: JavaFunctional): (JavaList[StaticParam], Type => Type) = {
      val own = toListFromImmutable(getStaticParameters(f, false))
      val env = typeAnalyzer.env
      val taken = own.map(_.getName.getText).toSet
      val clash = own.filter(p => env.contains(p.getName))
      if (clash.isEmpty) return (getStaticParameters(f, false), (t: Type) => t)
      val subst: List[(IdOrOp, IdOrOp)] = clash.map { p =>
        val n = p.getName
        val fresh = Iterator.from(1).map(i => NF.makeId(NU.getSpan(n), n.getText + "$" + i))
                            .find(m => !env.contains(m) && !taken.contains(m.getText)).get
        (n, fresh) }
      def apart(t: Type): Type = alphaRename(subst, t).asInstanceOf[Type]
      // every own parameter's bounds are renamed, so that a bound naming a renamed parameter names it still
      val renamed = own.map(p => {
        def bounds = toJavaList(toListFromImmutable(p.getExtendsClause).map(b => alphaRename(subst, b).asInstanceOf[BaseType]))
        subst.find(_._1 == p.getName) match {
          case Some((_, m)) => NF.makeStaticParam(p, m.asInstanceOf[Id], bounds)
          case None => p.getName match {
            case n: Id if !p.getExtendsClause.isEmpty => NF.makeStaticParam(p, n, bounds)
            case _ => p }
        } })
      (toJavaList(renamed), apart)
    }


    /* Whether the on-demand import i of the api index imports a functional or variable
     * whose name has the text name: once for the api, though several of its names have
     * that text, as a prefix and an infix operator do; and not where i's except clause
     * lists the name (source-code.tex, "Import Statements"). */
    private def importsOnDemand(index: CompilationUnitIndex, i: ImportStar, name: String): Boolean =
      !toListFromImmutable(i.getExceptNames).exists(m => m.asInstanceOf[IdOrOp].getText.equals(name)) &&
      (toSet(index.functions.firstSet).exists(n => n.asInstanceOf[IdOrOp].getText.equals(name)) ||
       toSet(index.variables.keySet).exists(n => n.asInstanceOf[IdOrOp].getText.equals(name)))

    /* Called by com.sun.fortress.compiler.StaticChecker.checkComponent
     *       and com.sun.fortress.compiler.StaticChecker.checkApi
     */
    def checkOverloading(): JavaList[StaticError] = {
        val fnsInComp = compilation_unit.functions
        val functions = fnsInComp.firstSet
        val ast = compilation_unit.ast
        val kindAndName = (compilation_unit match { case _:ComponentIndex => "component "; case _:ApiIndex => "API " }) + compilation_unit.name
        val importItems = toListFromImmutable(ast.getImports)
        val importStars = importItems.filter(_.isInstanceOf[ImportStar]).map(_.asInstanceOf[ImportStar])
        val importNames = importItems.filter(_.isInstanceOf[ImportNames]).map(_.asInstanceOf[ImportNames])

        // First check names of functions declared in this component.
        for ( f <- toSet(functions) ; if isCheckedName(f) ) {
          val name = f.asInstanceOf[IdOrOp].getText
          var set = getFunctionsFromCompilationUnit(compilation_unit, f)

          for ( i <- importNames ) {
            for ( n <- toListFromImmutable(i.getAliasedNames) ) {
              if ( n.getAlias.isSome &&
                   n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                set ++= getFunctions(globalEnv.lookup(i.getApiName), n.getName)
              } else if ( n.getAlias.isNone &&
                          n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                set ++= getFunctions(globalEnv.lookup(i.getApiName), f)
              }
            }
          }

          for ( i <- importStars ) {
            val index = globalEnv.lookup(i.getApiName)
            // get the JavaFunctionals from the api and add them to set
            if ( importsOnDemand(index, i, name) ) set ++= getFunctions(index, f)
          }

          // debugging probe: TypeError.b3(name, f, set)
          checkFunctionOverloading(kindAndName, f, set, globalOracle)

          val dFunctions = getDeclaredFunctions(compilation_unit, f)

          var fMethods = getFunctionalMethods(compilation_unit, f)

          for ( i <- importNames ) {
            for ( n <- toListFromImmutable(i.getAliasedNames) ) {
              if ( n.getAlias.isSome &&
                   n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                fMethods ++= getFunctionalMethods(globalEnv.lookup(i.getApiName), n.getName)
              } else if ( n.getAlias.isNone &&
                          n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                fMethods ++= getFunctionalMethods(globalEnv.lookup(i.getApiName), f)
              }
            }
          }

          for ( i <- importStars ) {
            val index = globalEnv.lookup(i.getApiName)
            // get the JavaFunctionals from the api and add them to set
            if ( importsOnDemand(index, i, name) ) fMethods ++= getFunctionalMethods(index, f)
          }          

          checkFancyRule(f, dFunctions, fMethods, globalOracle)

        }

        // Overloading checking for imported functionals that are not declared in this component
        for ( f <- importNames ) {
          for ( g <- toListFromImmutable(f.getAliasedNames);
                if (g.getAlias.isSome && ! toSet(functions).contains(g.getAlias.unwrap)) ||
                   ! toSet(functions).contains(g.getName) ) {
            val name = if (g.getAlias.isSome) g.getAlias.unwrap.asInstanceOf[IdOrOp].getText
                       else g.getName.asInstanceOf[IdOrOp].getText
            var set = getFunctions(globalEnv.lookup(f.getApiName), g.getName)
            for ( i <- importNames ; if ! f.getApiName.getText.equals(i.getApiName.getText)) {
              for ( n <- toListFromImmutable(i.getAliasedNames) ) {
                if ( n.getAlias.isSome &&
                     n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(globalEnv.lookup(i.getApiName), n.getName)
                } else if ( n.getAlias.isNone &&
                            n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(globalEnv.lookup(i.getApiName), g.getName)
                }
              }
            }
            for ( i <- importStars ) {
              val index = globalEnv.lookup(i.getApiName)
              // get the JavaFunctionals from the api and add them to set
              if ( importsOnDemand(index, i, name) ) set ++= getFunctions(index, g.getName)
            }
            checkFunctionOverloading(kindAndName, g.getName, set, globalOracle)
          }
        }

        // All inherited abstract methods in objects should have implementations.
        if ( compilation_unit.isInstanceOf[ComponentIndex] )
          errors = errors ::: new AbstractMethodChecker(compilation_unit.asInstanceOf[ComponentIndex],
                                                        globalEnv).check()

        // Now check trait and object declarations.
        val typesInComp = compilation_unit.typeConses
        for ( t <- toSet(typesInComp.keySet) ; if NU.isTraitOrObject(typesInComp.get(t)) ) {
            val traitOrObject = typesInComp.get(t).asInstanceOf[TraitIndex]
            val traitKindAndName = (traitOrObject match { case _:ObjectTraitIndex => "object "; case _ => "trait " }) + NU.getName(traitOrObject.ast)
            // Extend the type analyzer with the collected static parameters
            val oldTypeAnalyzer = typeAnalyzer
            // Add static parameters of the enclosing trait or object
            typeAnalyzer = typeAnalyzer.extend(toListFromImmutable(traitOrObject.staticParameters),
                                               None)
            staticParamsInScope = toListFromImmutable(traitOrObject.staticParameters)
            val oracle = new OverloadingOracle()(typeAnalyzer)
            /* The parameter type of a setter must be the same as the return type
             * of a getter with the same name, if any.
             */
            for ( f <- toSet(traitOrObject.setters.keySet) ) {
                if ( traitOrObject.getters.keySet.contains(f) ) {
                    val getter = traitOrObject.getters.get(f)
                    // Setter declarations are guaranteed to have a single parameter.
                    val param = traitOrObject.setters.get(f).parameters.get(0)
                    val span = getter.getSpan
                    if ( param.getIdType.isSome ) {
                        if (! isTrue(typeAnalyzer.equivalent(NU.optTypeOrPatternToType(param.getIdType).unwrap,
                                                      getter.getReturnType.unwrap))(typeAnalyzer) )
                            error(span,
                                  "The parameter type of a setter must be " +
                                  "the same as\n    the return type of a getter " +
                                  "with the same name, if any.")
                    }
                }
            }

            val tt = STypesUtil.declToTraitType(traitOrObject.ast)
	        // the methods the trait or object provides, by the traits chapter's inheritance
	        val (methodsR, overridden) = providedAndOverridden(tt, allMethods(tt, typeAnalyzer), typeAnalyzer, paramsWithoutSelf)

	        for (f <- toSet(methodsR.firstSet) ; if isCheckedName(f) ) {
                  val mset = toSet(methodsR.matchFirst(f))
	              val dottedMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaMethod] &&
	      	      		  		     	     	      m.asInstanceOf[JavaMethod].selfType.isSome })  // unsure why this second condition
	              checkMethodOverloading(traitKindAndName, f, toMethodArrows(dottedMethods), oracle)
	              val functionalMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaFunction]})
	              checkMethodOverloading(traitKindAndName, f, toFunctionalMethodArrows(functionalMethods, oracle), oracle)
	        }
	        // a declaration and one it keeps from being inherited: their return types
	        for ((f, o, p, equal) <- overridden ; if isCheckedName(f))
	          checkOverridingReturnType(f, o, p, equal, oracle)
            typeAnalyzer = oldTypeAnalyzer
            staticParamsInScope = Nil
        }
        toJavaList(errors)
    }

    private def checkFancyRule(name: IdOrOpOrAnonymousName,
    	    		       dFunctions: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       fMethods: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       oracle: OverloadingOracle) = {
      // These variables are used to improve the error message
      var x: ArrowType = null 
      var y: ArrowType = null  
      if (!dFunctions.forall(f => fMethods.forall( m => if (!(oracle.lteq(f._1,m._1))) true else { x = f._1; y = m._1; false } )))

    case (s@STupleType(_, e1, None, _), t@STupleType(_, e2, Some(v2), _)) => pExc(t, s)
    case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) if (e1.size == e2.size) =>
      pOr((e1, e2).zipped.map((a, b) => pExc(a, b)))
    case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) =>
      pTrue()
    // A tuple type excludes the library's Index only where one of its element types excludes Index.
    case (STupleType(_, e1, None, _), t: TraitType) if e1.nonEmpty && isLibraryIndex(t) =>
      pOr(e1.map(pExc(_, t)))
    case (s: TupleType, t) => pExc(disjunctFromTuple(s, 1), t)
    case (s, t: TupleType) => pExc(t, s)
    case (s: ArrowType, t: ArrowType) => pFalse()
    case (s: ArrowType, t) => pTrue()
    case (s, t: ArrowType) => pExc(t, s)
  }

  protected def removeSelf(x: Type) = {
    object remover extends Walker {
      override def walk(y: Any): Any = y match {
        case t:TraitSelfType =>
          if (selfComprised(t).isEmpty)
            t.getNamed
          else
            NF.makeIntersectionType(t.getNamed, NF.makeMaybeUnionType(t.getComprised))
        case t:ObjectExprType => NF.makeMaybeIntersectionType(t.getExtended)
        case _ => super.walk(y)
      }
    }
    remover(x).asInstanceOf[Type]
  }
  /*
   * For is-subtype queries, it makes no sense to stir in the comprised types;
   * if this is a subtype, then so are they
   * (unless they are declared to exclude -- but does that matter?) 
   */
  protected def removeSelfAsSubtype(x: Type) = {
    object remover extends Walker {
      override def walk(y: Any): Any = y match {
        case t:TraitSelfType => t.getNamed
        case t:ObjectExprType => NF.makeMaybeIntersectionType(t.getExtended)
        case _ => super.walk(y)
      }
    }
    remover(x).asInstanceOf[Type]
  }

  /* The types that self's type t lists beside its trait, as this analyzer reads them: none
   * where the trait's comprises clause lists them at a where-clause variable that the kind
   * environment does not bind, as outside the trait's declaration, where a functional
   * method's signature is read. The trait comprises its listed types at every value of the
   * variable, so the trait type alone holds the values that its self type holds. */
  def selfComprised(t: TraitSelfType): List[NamedType] = {
    val comprised = toListFromImmutable(t.getComprised)
    if (comprised.isEmpty) Nil
    else t.getNamed match {
      case tt: TraitType => toOption(traits.typeCons(tt.getName)) match {
        case Some(ti: ProperTraitIndex) if whereSizes(ti).exists(w => {
            traits.readContext(); env.staticParam(w.getName).isEmpty }) => Nil
        case _ => comprised
      }
      case _ => comprised
    }
  }


