                case SWhereExtends(_, n, supers) if n.getText == b.getName.getText => supers }.flatten
              NF.makeTypeParam(NU.getSpan(b), b.getName,
                               toJavaList(toListFromImmutable(b.getSupers) ++ constraints), none[Type], false)
